CREATE TABLE "player_ratings" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "player_ratings_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nickname" text NOT NULL,
	"month" text NOT NULL,
	"device_hash" text NOT NULL,
	"score" integer NOT NULL,
	"content" text DEFAULT '' NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "player_ratings_nickname_check" CHECK (char_length(btrim("nickname")) BETWEEN 1 AND 80),
	CONSTRAINT "player_ratings_month_check" CHECK ("month" ~ '^\d{4}-(0[1-9]|1[0-2])$'),
	CONSTRAINT "player_ratings_score_check" CHECK ("score" BETWEEN 1 AND 10),
	CONSTRAINT "player_ratings_content_check" CHECK (char_length("content") <= 120)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "player_ratings_player_month_device_idx" ON "player_ratings" ("nickname","month","device_hash");--> statement-breakpoint
CREATE INDEX "player_ratings_nickname_month_idx" ON "player_ratings" ("nickname","month");